<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/social_loans_fixture.php';
function blocked(callable $fn,string $label):void{try{$fn();}catch(InvalidArgumentException $e){return;}throw new RuntimeException($label);}
foreach(['youtube'=>'https://youtu.be/dQw4w9WgXcQ','tiktok'=>'https://www.tiktok.com/@test','facebook'=>'https://facebook.com/test','instagram'=>'https://instagram.com/test','x'=>'https://x.com/test','linkedin'=>'https://linkedin.com/in/test'] as $platform=>$url)expect(SocialHub::url($platform,$url)===$url,'Platform URL rejected');
foreach(['https://youtube.com.evil.test/watch','javascript:alert(1)','http://youtube.com/test','https://u:p@youtube.com/test','https://youtube.com:8080/test'] as $url)blocked(fn()=>SocialHub::url('youtube',$url),'Unsafe link accepted');
