SocialHub::review(3,$second['id'],'rejected','Slots exhausted');
expect((float)Wallet::getWallet(201)['withdrawable_balance']===0.0,'Rejected submission credited');
blocked(fn()=>SocialHub::submit(203,$task,'Suspended'),'Suspended user submitted a task');
