SocialHub::requestPromotion(200,$promo);SocialHub::requestPromotion(200,$promo);
expect(Database::count('social_promotions')===1,'Duplicate promotion request');
$order=Database::fetchOne('SELECT * FROM social_promotions');$id=(int)$order['id'];
