blocked(fn()=>SocialHub::quote(3,$id,$quote),'Underfunded quotation accepted');
$quote['price']='12000'; SocialHub::quote(3,$id,$quote);
blocked(fn()=>SocialHub::payPromotion(201,$id,1),'Another user paid a promotion');
