$after=Wallet::getWallet(200);
expect((float)$before['balance']-(float)$after['balance']===12000.0,'Promotion was not charged exactly once');
expect((float)$before['withdrawable_balance']-(float)$after['withdrawable_balance']===12000.0,'Promotion did not reduce spendable funds');
expect($before['total_withdrawn']===$after['total_withdrawn'],'Promotion incorrectly changed payout totals');
SocialHub::publish(3,$id);SocialHub::publish(3,$id);
expect(Database::count('social_campaigns','promotion_id=?',[$id])===1,'Paid campaign published twice');
$published=Database::fetchOne('SELECT id FROM social_campaigns WHERE promotion_id=?',[$id]);
blocked(fn()=>SocialHub::submit(200,$published['id'],'Own campaign'),'Owner earned own reward');
blocked(fn()=>SocialHub::cancelPromotion(200,$id),'Published campaign refunded without review');
$promo['request_key']='request-promotion-2';SocialHub::requestPromotion(200,$promo);$refundId=(int)Database::fetchOne('SELECT MAX(id) AS id FROM social_promotions')['id'];
$quote['price']='1000';$quote['reward']='100';$quote['slots']='5';SocialHub::quote(3,$refundId,$quote);
$before=Wallet::getWallet(200);SocialHub::payPromotion(200,$refundId,1);SocialHub::cancelPromotion(200,$refundId);SocialHub::cancelPromotion(200,$refundId);
expect(Wallet::getWallet(200)['balance']===$before['balance'],'Refund was not exactly once');
$promo['request_key']='completed-promotion';$promo['slots']='1';SocialHub::requestPromotion(201,$promo);
