Wallet::credit(201,1000,'social_reward','Test funds');SocialHub::payPromotion(201,$completeId,1);SocialHub::publish(3,$completeId);
$completeTask=(int)Database::fetchOne('SELECT id FROM social_campaigns WHERE promotion_id=?',[$completeId])['id'];
