SocialHub::review(3,$completeSubmission,'approved','Accepted');
expect(Database::fetchOne('SELECT status FROM social_promotions WHERE id=?',[$completeId])['status']==='completed','Paid campaign did not complete after last reward');
blocked(fn()=>SocialHub::toggle(3,$completeTask),'Completed task reopened');
$promo['request_key']='held-funds-promotion';SocialHub::requestPromotion(202,$promo);
$heldId=(int)Database::fetchOne('SELECT MAX(id) AS id FROM social_promotions')['id'];
SocialHub::quote(3,$heldId,['price'=>'2000','reward'=>'100','slots'=>'1','terms'=>'Feedback only']);
Wallet::credit(202,10000,'social_reward','Test funds');Database::update('wallets',['pending_amount'=>9500],'user_id = ?',[202]);
$heldBefore=Wallet::getWallet(202);blocked(fn()=>SocialHub::payPromotion(202,$heldId,1),'Held payout money funded a promotion');
expect(Wallet::getWallet(202)===$heldBefore,'Rejected held-fund payment changed wallet');
