LoanApplications::savePolicy(3,$policy);$current=LoanApplications::policy();
$application=['purpose'=>'Business equipment','request_key'=>'loan-request-1','accepted'=>'1','amount'=>'5000','terms_hash'=>LoanApplications::hash($current)];
blocked(fn()=>LoanApplications::apply(203,$application),'Suspended user requested a loan');
