LoanApplications::apply(200,$application);LoanApplications::apply(200,$application);
expect(Database::count('loan_applications')===1,'Loan submitted twice');
$application['request_key']='loan-request-2';blocked(fn()=>LoanApplications::apply(200,$application),'Multiple open loans allowed');
