expect(Database::fetchOne('SELECT terms_snapshot FROM loan_applications')['terms_snapshot']===$loan['terms_snapshot'],'Published terms changed a prior agreement');
LoanApplications::review(3,$loan['id'],'closed','Application follow-up completed.');
expect(StaffAccess::pagePermission('social')==='social' && StaffAccess::pagePermission('loans')==='loans','Agent route permissions missing');
echo "Social/loans: reward caps and duplicate protection, price budget, owned payments, stale quotes, exactly-once refunds, loan terms and no-disbursement checks passed. No external money moved.\n";
